-- Conferência
select i->>'sigla' as sigla, i->>'materia' as materia, i->>'professor' as professor, i->>'foto' as foto
  from conteudo.platform_config, jsonb_array_elements(landing->'cursos'->'itens') i
 where id = 'default';
